<script setup lang="ts">
import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()
import {ref,onUnmounted} from 'vue';export interface ManagedFile{id:string;name:string;size:number;url?:string}const files=defineModel<ManagedFile[]>({default:()=>[]});const emit=defineEmits<{upload:[files:File[]];remove:[id:string];download:[id:string]}>();const dragging=ref(false);function add(input:FileList|null){if(!input)return;emit('upload',Array.from(input));dragging.value=false}function drop(e:DragEvent){e.preventDefault();add(e.dataTransfer?.files||null)}onUnmounted(()=>dragging.value=false);function format(n:number){return n<1024?n+' B':(n/1024).toFixed(1)+' KB'}
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-ent-panel"><label class="hys-ui-ent-drop" :class="{'hys-ui-dragging':dragging}" @dragenter.prevent="dragging=true" @dragleave.prevent="dragging=false" @dragover.prevent @drop="drop"><input type="file" multiple @change="add(($event.target as HTMLInputElement).files);($event.target as HTMLInputElement).value=''"/>拖拽文件至此或点击选择（由业务层负责上传）</label><ul class="hys-ui-ent-files"><li v-for="f in files" :key="f.id"><span>{{f.name}} · {{format(f.size)}}</span><button type="button" @click="emit('download',f.id)">下载</button><button type="button" @click="emit('remove',f.id)">移除</button></li></ul><p v-if="!files.length" class="hys-ui-ent-muted">暂无附件</p></div></template>
